const raw = $input.first().json.output || $input.first().json.text || '';
const userPrompt = $('Edit Fields').first().json.user_prompt;

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('Planning Agent did not return JSON. Raw output: ' + raw);
}

let plan;
try {
  plan = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error('Invalid JSON from Planning Agent: ' + raw);
}

plan.duration = Number(plan.duration) || 60;
plan.platform = plan.platform || 'Instagram Reels';
plan.topic = plan.topic || userPrompt;

return [{ json: { user_prompt: userPrompt, plan } }];

const raw = $input.first().json.output || $input.first().json.text || '';
const saved = $('Save Script').first().json;

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('Scene Agent did not return JSON. Raw output: ' + raw);
}

let data;
try {
  data = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error('Invalid JSON from Scene Agent: ' + raw);
}

if (!Array.isArray(data.scenes) || data.scenes.length === 0) {
  throw new Error('No scenes found. Raw output: ' + raw);
}

const targetDuration = saved.plan.duration || 60;

let scenes = data.scenes.map((s, i) => ({
  scene_number: Number(s.scene_number) || i + 1,
  narration: String(s.narration || '').trim(),
  visual_description: String(s.visual_description || '').trim(),
  search_keywords: String(s.search_keywords || saved.topic).trim(),
  duration_seconds: Number(s.duration_seconds) || 6,
}));

// Rescale durations so the total matches the requested length
const total = scenes.reduce((sum, s) => sum + s.duration_seconds, 0);
const factor = targetDuration / total;
scenes = scenes.map(s => ({
  ...s,
  duration_seconds: Math.max(2, Math.round(s.duration_seconds * factor * 10) / 10),
}));

// Zero-padded file names for later steps (scene_01.jpg)
return scenes.map(s => ({
  json: {
    ...s,
    scene_id: String(s.scene_number).padStart(2, '0'),
    topic: saved.topic,
    total_scenes: scenes.length,
    full_script: saved.script,
  },
}));

parameters.text:
=Create a stock-photo search query for this scene.

Narration: {{ $json.narration }}
Visual description: {{ $json.visual_description }}
Keywords: {{ $json.search_keywords }}

Rules: use 1 to 3 simple words about something photographable.
Return ONLY the search query. No quotes, no explanation.

parameters.jsCode:
const sceneNow = $('Loop Over Items').item.json;
const alreadyHave = ['01','02','03','04','05','06','07','08'];
if (alreadyHave.includes(String(sceneNow.scene_id))) {
  return { json: { ...sceneNow, image_url: null, file_path: `/home/node/.n8n-files/visuals/scene_${sceneNow.scene_id}.jpg`, skip: true } };
}
const API_KEY = '*';

const scene = $('Loop Over Items').item.json;
const clean = s => String(s || '')
  .replace(/["'`.,!?:;()]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const agentQuery = clean($json.output);
const words = agentQuery.split(' ').filter(Boolean);
const kwRaw = Array.isArray(scene.search_keywords)
  ? scene.search_keywords.join(' ')
  : scene.search_keywords;
const kwWords = clean(kwRaw).split(' ').filter(Boolean);

// Try the most specific query first, then simpler and simpler ones
const candidates = [...new Set([
  agentQuery,
  words.slice(0, 2).join(' '),
  words[0],
  kwWords.slice(0, 2).join(' '),
  kwWords[0],
  'students learning',
  'technology',
])].filter(Boolean);

let chosen = null;
let usedQuery = '';

for (const q of candidates) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://pixabay.com/api/',
    qs: {
      key: API_KEY,
      q,
      image_type: 'photo',
      safesearch: 'true',
      per_page: 20,
    },
    json: true,
  });
  const hits = res.hits || [];
  if (hits.length) {
    // prefer a portrait photo (good for 9:16), otherwise take the first
    chosen = hits.find(h => h.imageHeight > h.imageWidth) || hits[0];
    usedQuery = q;
    break;
  }
}

if (!chosen) {
  throw new Error(`No Pixabay results for scene ${scene.scene_number}. Tried: ${candidates.join(' | ')}`);
}

return {
  json: {
    ...scene,
    visual_query: usedQuery,
    image_url: chosen.largeImageURL,
       file_path: `/home/node/.n8n-files/visuals/scene_${scene.scene_id}.jpg`,
  },
};

