const raw = String($input.first().json.output || '');
const match = raw.match(/\{[\s\S]*\}/);
let seo = { title: 'Untitled', description: '', hashtags: [] };
try { if (match) seo = JSON.parse(match[0]); } catch (e) {}
return [{ json: {
  qc_status: $('Parse QC').first().json.qc_status,
  qc_reasons: $('Parse QC').first().json.qc_reasons,
  title: seo.title,
  description: seo.description,
  hashtags: seo.hashtags
}}];

const text = $input.all()
  .map(i => String(i.json.narration || '').trim())
  .filter(Boolean)
  .join(' ');

return [{ json: { voiceover_text: text, scene_count: $input.all().length } }];

const script = $('Build Voiceover Text').first().json.voiceover_text;

const ask = async (prompt) => {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/generate',
    body: { model: 'llama3.2', prompt, stream: false, format: 'json', options: { temperature: 0.2 } },
    json: true,
    timeout: 300000,
  });
  return JSON.parse(r.response);
};

let qc = { status: 'FAIL', reasons: ['QC call failed'] };
let seo = { title: '', description: '', hashtags: [] };
let error = null;

try {
  qc = await ask(`You are a quality-control reviewer for a short Instagram Reel script.
Script: ${script}
Rules: it is about AI in education, has a clear hook in the first sentence, is 60 to 200 words, and has no misleading claims.
Return JSON only: {"status": "PASS" or "FAIL", "reasons": ["short reason"]}`);

  seo = await ask(`Create social media metadata for this Reel script.
Script: ${script}
Return JSON only: {"title": "max 70 characters", "description": "max 200 characters", "hashtags": ["#a","#b","#c","#d","#e"]}`);
} catch (e) {
  error = String(e.message || e);
}

return [{ json: {
  qc_status: String(qc.status || '').toUpperCase() === 'PASS' ? 'PASS' : 'FAIL',
  qc_reasons: qc.reasons || [],
  title: seo.title,
  description: seo.description,
  hashtags: seo.hashtags,
  error,
}}];
